create temporary view user_duration_search_raw_${grass_region_without_quote} as
select
    user_id
    ,coalesce(page_tag, 'null') as page_tag
    ,coalesce(source1_page_tag, 'null') as source1_page_tag
    ,coalesce(source2_page_tag, 'null') as source2_page_tag
    ,sum(duration) as duration
